    void StartRepeat(){repeatScheduled=false;if(repeatPaused){repeatRunning=true;repeatPaused=false;repeatTarget=DateTime.UtcNow.AddSeconds(repeatRemaining);}else if(!repeatRunning){repeatRunning=true;repeatRemaining=repeatLength;repeatTarget=DateTime.UtcNow.AddSeconds(repeatLength);}repeatMark=DateTime.UtcNow;SaveState();UpdateRepeatButtons();UpdateTray();}
