    void ExitApp(){exiting=true;tick.Stop();SaveState();foreach(WidgetForm w in widgets.Values)w.Close();widgets.Clear();if(tray!=null){tray.Visible=false;tray.Dispose();}Close();}
    void BuildWidgetsFromConfig(){EnsureConfig();foreach(string k in new string[]{"clock","alarm","world","timer","repeat","stopwatch"})if(ReadWidgetConfig(k))AddWidget(k);}
    void RefreshWidgets(){foreach(string k in new string[]{"alarm","world","timer","repeat","stopwatch"}){bool on=ReadWidgetConfig(k);if(on&&!widgets.ContainsKey(k))AddWidget(k);if(!on&&widgets.ContainsKey(k)){widgets[k].Close();widgets.Remove(k);}}ReflowWidgets();}
