    void ReflowWidgets(){if(widgets.Count==0)return;Rectangle wa=Screen.PrimaryScreen.WorkingArea;int bottom=wa.Bottom-14;foreach(string k in new string[]{"clock","alarm","world","timer","repeat","stopwatch"})if(widgets.ContainsKey(k)&&widgets[k].Visible){WidgetForm w=widgets[k];w.Left=wa.Right-w.Width-14;w.Top=bottom-w.Height;bottom=w.Top-7;}}
    bool ReadWidgetConfig(string key){try{Dictionary<string,object> d=json.DeserializeObject(File.ReadAllText(configPath)) as Dictionary<string,object>;return d!=null&&d.ContainsKey(key)&&Convert.ToBoolean(d[key]);}catch{return key=="clock";}}
    void EnsureConfig(){if(!File.Exists(configPath))File.WriteAllText(configPath,"{\"clock\":true,\"alarm\":false,\"world\":false,\"timer\":false,\"repeat\":false,\"stopwatch\":false}");}
    void SetWidgetConfig(string key,bool value){Dictionary<string,object>d=new Dictionary<string,object>();foreach(string k in new string[]{"clock","alarm","world","timer","repeat","stopwatch"})d[k]=(k=="clock")||((k==key)?value:ReadWidgetConfig(k));File.WriteAllText(configPath,json.Serialize(d),new UTF8Encoding(false));}
    string ReadMusicLink(){try{return File.ReadAllText(Path.Combine(Root,"apple_music_link.txt")).Trim();}catch{return "";}}
    void LoadState(){try{if(!File.Exists(statePath))return;Dictionary<string,object>d=json.DeserializeObject(File.ReadAllText(statePath)) as Dictionary<string,object>;if(d==null)return;string n;if(d.ContainsKey("nextAlarmUtc")){n=Convert.ToString(d["nextAlarmUtc"]);DateTime dt;if(DateTime.TryParse(n,null,DateTimeStyles.AdjustToUniversal|DateTimeStyles.AssumeUniversal,out dt)){repeatTarget=dt.ToUniversalTime();repeatLength=ParseInterval(Convert.ToString(d["interval"]),10800);repeatRemaining=Math.Max(0,(repeatTarget-DateTime.UtcNow).TotalSeconds);repeatRunning=Val(d,"running",false)&&repeatRemaining>0;repeatPaused=Val(d,"paused",false);if(repeatPaused)repeatRunning=false;repeatScheduled=Val(d,"repeatScheduled",false);DateTime rs;if(repeatScheduled&&DateTime.TryParse(Convert.ToString(d.ContainsKey("repeatStartAt")?d["repeatStartAt"]:""),null,DateTimeStyles.RoundtripKind,out rs)){repeatStartAt=rs;if(repeatStartAt<=DateTime.Now)repeatScheduled=false;}}}if(d.ContainsKey("timerRemainingSeconds"))timerRemaining=Num(d,"timerRemainingSeconds",900);timerRunning=Val(d,"timerRunning",false);timerPaused=Val(d,"timerPaused",false);if(d.ContainsKey("timerEndUtc")){DateTime t;if(DateTime.TryParse(Convert.ToString(d["timerEndUtc"]),null,DateTimeStyles.AssumeUniversal|DateTimeStyles.AdjustToUniversal,out t))timerTarget=t.ToUniversalTime();}stopwatchSeconds=Num(d,"stopwatchSeconds",0);swRunning=Val(d,"stopwatchRunning",false);alarmActive=Val(d,"alarmActive",false);alarmIsDaily=Val(d,"alarmDaily",false);DateTime a;if(DateTime.TryParse(Convert.ToString(d.ContainsKey("alarmAt")?d["alarmAt"]:""),out a))alarmAt=a;}catch{} }
    static bool Val(Dictionary<string,object>d,string k,bool f){try{return d.ContainsKey(k)&&Convert.ToBoolean(d[k]);}catch{return f;}} static double Num(Dictionary<string,object>d,string k,double f){try{return Convert.ToDouble(d[k],CultureInfo.InvariantCulture);}catch{return f;}} static double ParseInterval(string s,double f){TimeSpan t;if(TimeSpan.TryParse(s,out t))return t.TotalSeconds;return f;}
    void SaveState(){if(!initialized)return;try{double rem=repeatRunning?Math.Max(0,(repeatTarget-DateTime.UtcNow).TotalSeconds):repeatRemaining;double tr=timerRunning?Math.Max(0,(timerTarget-DateTime.UtcNow).TotalSeconds):timerRemaining;string next=repeatScheduled?repeatStartAt.ToUniversalTime().ToString("o",CultureInfo.InvariantCulture):repeatTarget==DateTime.MinValue?"":repeatTarget.ToString("o",CultureInfo.InvariantCulture);string end=timerRunning?timerTarget.ToString("o",CultureInfo.InvariantCulture):"";string alarm=alarmActive?alarmAt.ToString("o",CultureInfo.InvariantCulture):"";Dictionary<string,object>d=new Dictionary<string,object>();d["updatedUtc"]=DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture);d["nextAlarmUtc"]=next;d["appRunning"]=true;d["running"]=repeatRunning;d["paused"]=repeatPaused;d["repeatScheduled"]=repeatScheduled;d["repeatStartAt"]=repeatScheduled?repeatStartAt.ToString("o",CultureInfo.InvariantCulture):"";d["remainingSeconds"]=rem;d["interval"]=TimeSpan.FromSeconds(repeatLength).ToString("c");d["timerRunning"]=timerRunning;d["timerPaused"]=timerPaused;d["timerRemainingSeconds"]=tr;d["timerEndUtc"]=end;d["alarmActive"]=alarmActive;d["alarmDaily"]=alarmIsDaily;d["alarmAt"]=alarm;d["stopwatchRunning"]=swRunning;d["stopwatchSeconds"]=stopwatchSeconds+(swRunning?(DateTime.UtcNow-stopwatchMark).TotalSeconds:0);d["widgets"]=json.DeserializeObject(File.Exists(configPath)?File.ReadAllText(configPath):"{}");string tmp=statePath+".tmp";File.WriteAllText(tmp,json.Serialize(d),new UTF8Encoding(false));if(File.Exists(statePath))File.Delete(statePath);File.Move(tmp,statePath);}catch{} }
    void Tick(object sender,EventArgs e){DateTime now=DateTime.Now;clockHeader.Text=now.ToString("HH:mm:ss");if(currentView=="home"){heroClock.Text=now.ToString("HH:mm:ss");heroDate.Text=now.ToString("dddd dd MMMM yyyy",new CultureInfo("it-IT"));}if(currentView=="repeat"){double r=repeatRunning?Math.Max(0,(repeatTarget-DateTime.UtcNow).TotalSeconds):repeatScheduled?Math.Max(0,(repeatStartAt-DateTime.Now).TotalSeconds):repeatRemaining;repeatValue.Text=Fmt(r);repeatStatus.Text=repeatScheduled?(repeatStartAt.Date==DateTime.Today?"Avvio oggi · alle ":"Avvio domani · alle ")+repeatStartAt.ToString("HH:mm"):repeatRunning?"Attivo · ogni "+TimeSpan.FromSeconds(repeatLength).ToString(@"h\:mm"):repeatPaused?"In pausa · riprendi quando vuoi":"Pronto · programma l’intervallo";}if(currentView=="timer")timerValue.Text=Fmt(timerRunning?Math.Max(0,(timerTarget-DateTime.UtcNow).TotalSeconds):timerRemaining);if(currentView=="stopwatch")swValue.Text=StopwatchText(stopwatchSeconds+(swRunning?(DateTime.UtcNow-stopwatchMark).TotalSeconds:0));if(currentView=="world"){foreach(Control c in FindLabels(content))if(c.Tag is string){string z=(string)c.Tag;try{TimeZoneInfo tz=TimeZoneInfo.FindSystemTimeZoneById(z);c.Text=z=="W. Europe Standard Time"?"Roma     "+TimeZoneInfo.ConvertTime(now,tz).ToString("HH:mm:ss"):CityName(z)+"     "+TimeZoneInfo.ConvertTime(now,tz).ToString("HH:mm:ss");}catch{}}}foreach(WidgetForm w in widgets.Values)w.UpdateText();if(repeatScheduled&&DateTime.Now>=repeatStartAt){repeatScheduled=false;repeatRunning=true;repeatPaused=false;repeatRemaining=repeatLength;repeatTarget=DateTime.UtcNow.AddSeconds(repeatLength);SystemSounds.Asterisk.Play();SaveState();}if(repeatRunning&&repeatTarget<=DateTime.UtcNow){repeatTarget=repeatTarget.AddSeconds(repeatLength);repeatRemaining=repeatLength;SystemSounds.Asterisk.Play();SaveState();}if(timerRunning&&timerTarget<=DateTime.UtcNow){timerRunning=false;timerPaused=false;timerRemaining=0;SystemSounds.Asterisk.Play();MessageBox.Show(this,"Il conto alla rovescia è terminato.","Ritmo · Timer terminato",MessageBoxButtons.OK,MessageBoxIcon.Information);}if(alarmActive&&alarmAt<=now){DateTime fired=alarmAt;if(alarmIsDaily){do{alarmAt=alarmAt.AddDays(1);}while(alarmAt<=now);}else alarmActive=false;SystemSounds.Asterisk.Play();MessageBox.Show(this,"È ora della sveglia.","Ritmo · Sveglia",MessageBoxButtons.OK,MessageBoxIcon.Information);SaveState();}if((DateTime.UtcNow-repeatMark).TotalSeconds>=1){repeatMark=DateTime.UtcNow;SaveState();UpdateTray();}}
    internal string RepeatDisplay { get { return Fmt(repeatRunning?Math.Max(0,(repeatTarget-DateTime.UtcNow).TotalSeconds):repeatScheduled?Math.Max(0,(repeatStartAt-DateTime.Now).TotalSeconds):repeatRemaining); } }
    internal string RepeatStatus { get { return repeatRunning?"Attivo · ogni "+TimeSpan.FromSeconds(repeatLength).ToString(@"h\:mm"):repeatPaused?"In pausa":repeatScheduled?(repeatStartAt.Date==DateTime.Today?"Avvio oggi · alle ":"Avvio domani · alle ")+repeatStartAt.ToString("HH:mm"):"Pronto"; } }
    internal string TimerDisplay { get { return Fmt(timerRunning?Math.Max(0,(timerTarget-DateTime.UtcNow).TotalSeconds):timerRemaining); } }
    internal string TimerStatus { get { return timerRunning?"In esecuzione":timerPaused?"In pausa":"Pronto"; } }
    internal string StopwatchDisplay { get { return StopwatchText(stopwatchSeconds+(swRunning?(DateTime.UtcNow-stopwatchMark).TotalSeconds:0)); } }
    internal string AlarmDisplay { get { return alarmActive?alarmAt.ToString("HH:mm"):"Nessuna"; } }
    internal void WidgetClosed(string key) { widgets.Remove(key); SetWidgetConfig(key,false); ReflowWidgets(); }
    static List<Control> FindLabels(Control root){List<Control> list=new List<Control>();foreach(Control c in root.Controls){if(c is Label)list.Add(c);if(c.HasChildren)list.AddRange(FindLabels(c));}return list;} static string CityName(string z){switch(z){case "GMT Standard Time":return "Londra";case "Eastern Standard Time":return "New York";case "Tokyo Standard Time":return "Tokyo";default:return "Sydney";}}
    static string Fmt(double sec){TimeSpan t=TimeSpan.FromSeconds(Math.Max(0,sec));return string.Format("{0:00}:{1:00}:{2:00}",(int)Math.Floor(t.TotalHours),t.Minutes,t.Seconds);}static string StopwatchText(double sec){TimeSpan t=TimeSpan.FromSeconds(sec);return string.Format("{0:00}:{1:00}:{2:00}.{3:00}",(int)Math.Floor(t.TotalHours),t.Minutes,t.Seconds,t.Milliseconds/10);}
}

internal class WidgetForm : Form {
    readonly RitmoForm app;readonly string key;Label primary,secondary,title;Button pin,close;bool pinned=false;
    internal WidgetForm(RitmoForm owner,string widgetKey){app=owner;key=widgetKey;Text="Ritmo · "+widgetKey;FormBorderStyle=FormBorderStyle.None;ShowInTaskbar=false;StartPosition=FormStartPosition.Manual;TopMost=false;Opacity=.68;BackColor=ColorTranslator.FromHtml("#151E29");Size=new Size(268,78);Padding=new Padding(10);Build();}
    void Build(){title=new Label{Text=key=="clock"?"ORA LOCALE":key.ToUpperInvariant(),ForeColor=ColorTranslator.FromHtml("#9CC8E4"),Font=new Font("Segoe UI",8F,FontStyle.Bold),AutoSize=true,Location=new Point(40,5)};Controls.Add(title);primary=new Label{ForeColor=ColorTranslator.FromHtml("#EAF2F8"),Font=new Font("Segoe UI Light",24F),AutoSize=true,Location=new Point(40,22)};Controls.Add(primary);secondary=new Label{ForeColor=ColorTranslator.FromHtml("#B3C1CC"),Font=new Font("Segoe UI",8F),AutoSize=true,Location=new Point(40,53)};Controls.Add(secondary);pin=new Button{Text="◇",FlatStyle=FlatStyle.Flat,ForeColor=ColorTranslator.FromHtml("#B8D9EC"),BackColor=Color.FromArgb(48,42,53,64),Size=new Size(27,29),Location=new Point(7,23)};pin.FlatAppearance.BorderSize=0;pin.Click+=delegate{pinned=!pinned;TopMost=pinned;pin.Text=pinned?"◆":"◇";};Controls.Add(pin);close=new Button{Text="×",FlatStyle=FlatStyle.Flat,ForeColor=ColorTranslator.FromHtml("#95A8B8"),BackColor=Color.Transparent,Size=new Size(25,25),Location=new Point(Width-32,5),Anchor=AnchorStyles.Top|AnchorStyles.Right};close.FlatAppearance.BorderSize=0;close.Click+=delegate{if(key!="clock"){Hide();app.WidgetClosed(key);} };Controls.Add(close);MouseDown+=Drag;title.MouseDown+=Drag;primary.MouseDown+=Drag;}
    void Drag(object sender,MouseEventArgs e){if(e.Button==MouseButtons.Left){Capture=false;Native.ReleaseCapture();Native.SendMessage(Handle,0xA1,new IntPtr(2),IntPtr.Zero);}}
    internal void UpdateText(){DateTime n=DateTime.Now;if(key=="clock"){primary.Text=n.ToString("HH:mm:ss");secondary.Text=n.ToString("dddd dd MMMM",new CultureInfo("it-IT"));}else if(key=="repeat"){primary.Text=app.RepeatDisplay;secondary.Text=app.RepeatStatus;}else if(key=="timer"){primary.Text=app.TimerDisplay;secondary.Text=app.TimerStatus;}else if(key=="stopwatch"){primary.Text=app.StopwatchDisplay;secondary.Text="Cronometro";}else if(key=="alarm"){primary.Text=app.AlarmDisplay;secondary.Text="Sveglia";}else{primary.Text=TimeZoneInfo.ConvertTime(n,TimeZoneInfo.FindSystemTimeZoneById("GMT Standard Time")).ToString("HH:mm:ss");secondary.Text="Londra";}}
    protected override void OnShown(EventArgs e){base.OnShown(e);UpdateText();}
    static class Native{[System.Runtime.InteropServices.DllImport("user32.dll")]internal static extern bool ReleaseCapture();[System.Runtime.InteropServices.DllImport("user32.dll")]internal static extern IntPtr SendMessage(IntPtr h,int m,IntPtr w,IntPtr l);}
}






